59			/* Used in tunnel GRO receive */
60			u8	encap_mark:1;
61	
62			/* GRO checksum is valid */
63			u8	csum_valid:1;
64	
65			/* Number of checksums via CHECKSUM_UNNECESSARY */
66			u8	csum_cnt:3;
67	
68			/* Free the skb? */
69			u8	free:2;
